action.mutation:
mutation CreateMasterInventory($payload: [MasterInventoryCreatePayloadInput!]!) {
  mutation: createMasterInventory(payload: $payload) { 
    id
    number
  }
}

mutation UpdateMasterInventory($payload: [MasterInventoryUpdatePayloadInput!]!) {
  mutation: updateMasterInventory(payload: $payload) { 
    id
    number
  }
}
